/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: installManagedCovers, json, toneOf, expectWholeTitle, contrast
 *   Constants: coverIds, covers, longTitle, neutralHero, neutralPane, untintedPane, compactPlayName, toneAlbum,
 *              toneHome
 * Tests
 *   - tints the Album header from its artwork, fits a long title, and reveals the compact header
 *   - Home follows the hovered or focused media card tone and falls back to neutral
 *   - animates tone changes over 600 ms unless reduced motion is requested
 *   - keeps the Album header and compact header usable on a phone
 *   - keeps keyboard focus below the visible compact header while moving back up the tracks
 * @end-catalog */

import type { Locator, Page } from '@playwright/test';
import { fileURLToPath } from 'node:url';

import type { ListenerAlbum, ListenerHome } from '../src/api/contentSchemas';

import { albumFixture, catalogIds, trackFixtures } from './fixtures/catalog';
import { expectNoUnownedAxeViolations } from './support/accessibility';
import { expect, test } from './support/test';

const coverIds = {
  dawn: '64b000000000000000000301',
  night: '64b000000000000000000302'
} as const;
const covers = new Map<string, string>([
  [coverIds.dawn, fileURLToPath(new URL('./fixtures/assets/first-light.jpg', import.meta.url))],
  [coverIds.night, fileURLToPath(new URL('./fixtures/assets/night-window.jpg', import.meta.url))]
]);
const longTitle = 'Chiikawa the Movie: The Secret of Mermaid Island (Original Motion Picture Soundtrack)';
const neutralHero = 'rgb(83, 83, 83)';
const neutralPane = 'rgb(51, 51, 51)';
const untintedPane = 'rgb(18, 18, 18)';
const compactPlayName = `Play album ${longTitle} by Finitude Ensemble`;

const toneAlbum = {
  album: { ...albumFixture, title: longTitle, artworkUrl: `/content/images/${coverIds.dawn}` },
  // Enough audio rows for the Album header to scroll out of the 1440 x 900 main pane.
  tracks: Array.from({ length: 14 }, (_, index) => ({
    ...trackFixtures[1],
    id: `e2e-tone-track-${index + 1}`,
    title: `Tone Study ${index + 1}`,
    streamUrl: `/content/mediaTrack/stream/e2e-tone-track-${index + 1}`
  }))
} satisfies ListenerAlbum;

const toneHome = {
  title: 'Tone room',
  sections: [{
    id: 'tone-albums',
    title: 'Albums with artwork',
    presentation: 'carousel',
    items: [
      { ...albumFixture, id: 'e2e-tone-dawn', title: 'Dawn Cover', artworkUrl: `/content/images/${coverIds.dawn}` },
      { ...albumFixture, id: 'e2e-tone-night', title: 'Night Cover', artworkUrl: `/content/images/${coverIds.night}` },
      { ...albumFixture, id: 'e2e-tone-blank', title: 'Blank Cover', artworkUrl: '' }
    ]
  }]
} satisfies ListenerHome;

/** Serves deterministic covers for managed artwork URLs and their 96 px variants; the browser sniffs the JPEG body. */
const installManagedCovers = async (page: Page) => {
  await page.route('**/content/images/**', async (route) => {
    const path = covers.get(new URL(route.request().url()).pathname.split('/')[3] ?? '');
    if (!path) {
      await route.fulfill({ status: 404, body: '' });
      return;
    }
    await route.fulfill({ status: 200, contentType: 'image/jpeg', path });
  });
};

const json = (body: unknown) => ({
  status: 200,
  contentType: 'application/json; charset=utf-8',
  headers: { 'Cache-Control': 'no-store' },
  body: JSON.stringify(body)
});

const toneOf = (element: Locator) => element.evaluate(
  (node) => getComputedStyle(node).getPropertyValue('--tone-color').trim()
);

/** WCAG 2 contrast between computed `rgb(r, g, b)` colors. */
/**
 * Rejects a clamped heading: the title's last character must sit on a visible line. Glyph boxes
 * overhang a tight line-height by a few pixels, so the check uses the glyph's vertical center; a
 * clamped character would sit at least a full line below the heading.
 */
const expectWholeTitle = async (heading: Locator) => {
  await expect.poll(() => heading.evaluate((element) => {
    const text = element.firstChild!;
    const range = document.createRange();
    range.setStart(text, text.textContent!.length - 1);
    range.setEnd(text, text.textContent!.length);
    const glyph = range.getBoundingClientRect();
    return (glyph.top + glyph.bottom) / 2 - element.getBoundingClientRect().bottom;
  })).toBeLessThan(0);
};

const contrast = (first: string, second: string) => {
  const luminance = (color: string) => {
    const [red, green, blue] = (color.match(/\d+/g) ?? []).map((channel) => {
      const value = Number(channel) / 255;
      return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
    });
    return 0.2126 * red + 0.7152 * green + 0.0722 * blue;
  };
  const [lighter, darker] = [luminance(first), luminance(second)].sort((left, right) => right - left);
  return (lighter + 0.05) / (darker + 0.05);
};

test.beforeEach(async ({ page }) => {
  await installManagedCovers(page);
  // Reduced motion applies tones at once so each poll reads a settled color.
  await page.emulateMedia({ reducedMotion: 'reduce' });
});

test('tints the Album header from its artwork, fits a long title, and reveals the compact header', async ({ page }) => {
  await page.route(`**/api/listener/v1/albums/${catalogIds.album}`, (route) => route.fulfill(json(toneAlbum)));
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.goto(`/finitude/albums/${catalogIds.album}`);

  const main = page.getByRole('main');
  const heading = page.getByRole('heading', { level: 1, name: longTitle });
  const hero = page.locator('header').filter({ has: heading });
  await expect(heading).toHaveAttribute('title', longTitle);
  await expectWholeTitle(heading);
  const lines = await heading.evaluate((element) => element.clientHeight / Number.parseFloat(getComputedStyle(element).lineHeight));
  expect(lines).toBeLessThanOrEqual(3.01);

  await expect.poll(() => toneOf(hero)).not.toBe(neutralHero);
  expect(contrast('rgb(255, 255, 255)', await toneOf(hero))).toBeGreaterThanOrEqual(4.5);
  // The opaque header paints the tone itself, so the main pane stays untinted beneath it.
  expect(await toneOf(main)).toBe(untintedPane);
  await expect(hero.getByText('Album', { exact: true })).toHaveCSS('color', 'rgb(255, 255, 255)');
  await expectNoUnownedAxeViolations(page, 'album-artwork-tone');

  const compactPlay = page.getByRole('button', { name: compactPlayName });
  await expect(compactPlay).toHaveCount(0);
  await main.evaluate((element) => element.scrollTo({ top: element.scrollHeight }));
  await expect(compactPlay).toBeVisible();
  const [barTop, mainTop] = await Promise.all([
    compactPlay.evaluate((element) => element.parentElement!.getBoundingClientRect().top),
    main.evaluate((element) => element.getBoundingClientRect().top)
  ]);
  expect(Math.abs(barTop - mainTop)).toBeLessThanOrEqual(1);
  const barTone = await toneOf(compactPlay.locator('..'));
  expect(barTone).not.toBe(neutralPane);
  expect(contrast('rgb(179, 179, 179)', barTone)).toBeGreaterThanOrEqual(4.5);

  await main.evaluate((element) => element.scrollTo({ top: 0 }));
  await expect(compactPlay).toHaveCount(0);
});

test('Home follows the hovered or focused media card tone and falls back to neutral', async ({ page }) => {
  await page.route('**/api/listener/v1/home', (route) => route.fulfill(json(toneHome)));
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.goto('/finitude/');

  const main = page.getByRole('main');
  const dawn = page.getByRole('link', { name: /^Dawn Cover/ });
  const night = page.getByRole('link', { name: /^Night Cover/ });
  await expect(dawn).toBeVisible();
  await expect.poll(() => toneOf(main)).toBe(neutralPane);

  await dawn.hover();
  await expect.poll(() => toneOf(main)).not.toBe(neutralPane);
  const dawnTone = await toneOf(main);
  await night.hover();
  await expect.poll(() => toneOf(main)).not.toBe(dawnTone);
  expect(await toneOf(main)).not.toBe(neutralPane);

  // A card without managed artwork and the space outside Home both return to neutral.
  await page.getByRole('link', { name: /^Blank Cover/ }).hover();
  await expect.poll(() => toneOf(main)).toBe(neutralPane);
  await night.hover();
  await expect.poll(() => toneOf(main)).not.toBe(neutralPane);
  await page.mouse.move(4, 4);
  await expect.poll(() => toneOf(main)).toBe(neutralPane);

  // Keyboard focus counts; focus is visible because no pointer press preceded it.
  await dawn.focus();
  expect(await dawn.evaluate((element) => element.matches(':focus-visible'))).toBe(true);
  await expect.poll(() => toneOf(main)).toBe(dawnTone);

  // Leaving Home in-app clears the tone so untoned routes keep the plain panel.
  await page.locator('#library-sidebar').getByRole('link', { name: 'Search' }).click();
  await expect(page).toHaveURL(/\/finitude\/search$/);
  await expect.poll(() => main.evaluate((element) => element.style.getPropertyValue('--tone-color'))).toBe('');
  await expect.poll(() => toneOf(main)).toBe('rgb(18, 18, 18)');
});

test('animates tone changes over 600 ms unless reduced motion is requested', async ({ page }) => {
  await page.route('**/api/listener/v1/home', (route) => route.fulfill(json(toneHome)));
  await page.goto('/finitude/');
  const main = page.getByRole('main');
  // The global reduced-motion sheet shortens every transition to 0.001 ms.
  await expect.poll(() => main.evaluate((element) => Number.parseFloat(getComputedStyle(element).transitionDuration)))
    .toBeLessThan(0.01);

  await page.emulateMedia({ reducedMotion: 'no-preference' });
  await expect(main).toHaveCSS('transition-duration', '0.6s');
  await expect(main).toHaveCSS('transition-property', '--tone-color');
});

test('keeps the Album header and compact header usable on a phone', async ({ page }) => {
  await page.route(`**/api/listener/v1/albums/${catalogIds.album}`, (route) => route.fulfill(json(toneAlbum)));
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto(`/finitude/albums/${catalogIds.album}`);

  const main = page.getByRole('main');
  const heading = page.getByRole('heading', { level: 1, name: longTitle });
  await expect(heading).toBeVisible();
  const box = await heading.boundingBox();
  expect(box!.height).toBeLessThan(844 / 3);
  const dimensions = await main.evaluate((element) => ({ scroll: element.scrollWidth, client: element.clientWidth }));
  expect(dimensions.scroll).toBeLessThanOrEqual(dimensions.client + 1);

  await main.evaluate((element) => element.scrollTo({ top: element.scrollHeight }));
  await expect(page.getByRole('button', { name: compactPlayName })).toBeVisible();
  await expectWholeTitle(heading);

  // The narrowest supported phone still shows the whole title.
  await main.evaluate((element) => element.scrollTo({ top: 0 }));
  await page.setViewportSize({ width: 320, height: 568 });
  await expectWholeTitle(heading);
  const narrow = await main.evaluate((element) => ({ scroll: element.scrollWidth, client: element.clientWidth }));
  expect(narrow.scroll).toBeLessThanOrEqual(narrow.client + 1);
});

test('keeps keyboard focus below the visible compact header while moving back up the tracks', async ({ page }) => {
  await page.route(`**/api/listener/v1/albums/${catalogIds.album}`, (route) => route.fulfill(json(toneAlbum)));
  await page.setViewportSize({ width: 1_440, height: 900 });
  await page.goto(`/finitude/albums/${catalogIds.album}`);

  const main = page.getByRole('main');
  const compactPlay = page.getByRole('button', { name: compactPlayName });
  const lastTrack = page.getByRole('button', { name: 'Play Tone Study 14' });
  await expect(lastTrack).toBeVisible();
  await main.evaluate((element) => element.scrollTo({ top: element.scrollHeight }));
  await expect(compactPlay).toBeVisible();
  await lastTrack.focus();

  let checked = 0;
  for (let step = 0; step < 40; step += 1) {
    await page.keyboard.press('Shift+Tab');
    const placement = await page.evaluate((name) => {
      const focused = document.activeElement as HTMLElement | null;
      // The bar is the compact Play's parent; it only counts while its header is visible.
      const bar = document.querySelector(`[data-visible] button[aria-label="${name}"]`)?.parentElement;
      if (!focused?.closest('ol') || !bar) return null;
      return { top: focused.getBoundingClientRect().top, barBottom: bar.getBoundingClientRect().bottom };
    }, compactPlayName);
    if (!placement) break;
    checked += 1;
    expect(placement.top).toBeGreaterThanOrEqual(placement.barBottom - 1);
  }
  expect(checked).toBeGreaterThan(20);
});
